# The four ride options from our object model (US4).
# seat_limit counts everyone in the car, including the organizer.
# base_fare and per_mile_rate are our own estimates, not real Uber or Lyft
# prices. We picked them so a UberXL from the airport to the Cathedral of
# Learning comes out to about $84, like our Sprint 1 scenario. They can be
# changed on the admin site.
RIDE_OPTIONS = [
    ("UberX", "Uber", 4, "4.00", "3.25"),
    ("UberXL", "Uber", 6, "5.00", "5.00"),
    ("Lyft Standard", "Lyft", 4, "4.00", "3.20"),
    ("Lyft XL", "Lyft", 6, "5.00", "4.90"),
]


def add_ride_options(apps, schema_editor):
    RideOption = apps.get_model("rides", "RideOption")
    for name, provider, seat_limit, base_fare, per_mile_rate in RIDE_OPTIONS:
        RideOption.objects.get_or_create(
            name=name,
            defaults={
                "provider": provider,
                "seat_limit": seat_limit,
                "base_fare": Decimal(base_fare),
                "per_mile_rate": Decimal(per_mile_rate),
            },
        )


def remove_ride_options(apps, schema_editor):
    RideOption = apps.get_model("rides", "RideOption")
    RideOption.objects.filter(name__in=[option[0] for option in RIDE_OPTIONS]).delete()


